function openSession(s=null,presetWodId=""){const f=$("#sessionform");f.reset();f.elements.session_date.max=today();f.elements.session_id.value=s?.id||"";f.elements.actual_comment.value=s?.actual_comment||"";f.elements.actual_comment.dataset.plannedDefault="";const weekEnd=addDays(selectedWeekStart,6),defaultDate=selectedWeekStart>today()?today():(weekEnd<today()?weekEnd:today()),sessionDate=s?.session_date||defaultDate;f.elements.session_date.value=sessionDate;f.elements.program_id.innerHTML=programs.map(p=>`<option value="${p.id}">${esc(p.name)}${p.is_default?" (par défaut)":""}</option>`).join("");let selectedProgram=s?programs.find(p=>p.id===s.program_id):null;if(!selectedProgram&&presetWodId)selectedProgram=programs.find(p=>(wodsByProgram[p.id]||[]).some(x=>x.id===presetWodId));if(!selectedProgram)selectedProgram=programForDate(sessionDate);if(selectedProgram)f.elements.program_id.value=selectedProgram.id;const pid=f.elements.program_id.value;fillWodOptions(pid,s?.wod_name==="Autres"?"other":(s?.wod_id||presetWodId));const selectedWod=(wodsByProgram[pid]||[]).find(w=>w.id===(s?.wod_id||presetWodId));fillActivitySelect(f.elements.activity_id,s?.activity_id||selectedWod?.activity_id||defaultActivity()?.id);f.elements.duration_minutes.value=s?.duration_minutes||selectedWod?.duration_minutes||defaultActivity()?.duration_minutes||60;const defaultStart=new Date(Date.now()-Number(f.elements.duration_minutes.value)*60000);f.elements.start_time.value=s?.started_at?new Date(s.started_at).toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit",hour12:false}):defaultStart.toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit",hour12:false});f.elements.start_time.dataset.manual="";f.elements.start_time.onchange=()=>{f.elements.start_time.dataset.manual="1"};f.elements.duration_minutes.oninput=()=>{if(!f.elements.start_time.dataset.manual){const d=new Date(Date.now()-Number(f.elements.duration_minutes.value||0)*60000);f.elements.start_time.value=d.toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit",hour12:false})}};renderSessionMovementChecks(pid,s?.id||"");if(!s)applyPlannedSessionNote();$("#sessiontitle").textContent=s?"Modifier la séance":"Enregistrer une séance";$("#sessiondialog").showModal()}
let choiceWodId="";function openWodChoice(wodId){const planned=weeklyPlans.some(x=>x.wod_id===wodId);if(selectedWeekStart<mondayOf(today())){openSession(null,wodId);return}if(planned){if(selectedWeekStart>mondayOf(today())){toast("Cette séance est planifiée pour une semaine future.");return}openSession(null,wodId);return}choiceWodId=wodId;const w=programs.flatMap(p=>wodsByProgram[p.id]||[]).find(x=>x.id===wodId);$("#wodchoicetitle").textContent=w?.name||"Que souhaites-tu faire ?";$("#choice-record").disabled=selectedWeekStart>mondayOf(today());$("#choice-plan").textContent="Planifier";$("#wodchoice").showModal()}$("#closewodchoice").onclick=()=>$("#wodchoice").close();$("#choice-record").onclick=()=>{const id=choiceWodId;$("#wodchoice").close();openSession(null,id)};$("#choice-plan").onclick=async()=>{const id=choiceWodId;try{await api("/weekly-plans",{method:"POST",body:JSON.stringify({week_start:selectedWeekStart,wod_id:id})});$("#wodchoice").close();await changeWeek(selectedWeekStart);toast("WOD planifié.")}catch(e){toast(e.message)}};
