function isLoadBased(method){return method==="load"||method==="force"}
function prKey(record){return record.movement_id+":"+(isLoadBased(record.measurement_method)?record.rep_count:record.measurement_method)}
function prValue(record){return isLoadBased(record.measurement_method)?Number(record.value).toLocaleString("fr-FR")+" kg":record.measurement_method==="distance"?Number(record.value).toLocaleString("fr-FR")+" m":Number(record.value).toLocaleString("fr-FR")+" reps"}
function renderPrChart(records){
 const sorted=[...records].sort((a,b)=>a.record_date.localeCompare(b.record_date)||a.created_at.localeCompare(b.created_at));
 const width=340,height=150,left=46,right=8,top=8,bottom=22,values=sorted.map(x=>Number(x.value)),max=Math.max(...values);
 const rawStep=(max||1)/4,magnitude=Math.pow(10,Math.floor(Math.log10(rawStep))),normalized=rawStep/magnitude;
 const step=(normalized<=1?1:normalized<=2?2:normalized<=2.5?2.5:normalized<=5?5:10)*magnitude;
 const axisMax=step*4,plotHeight=height-top-bottom,plotWidth=width-left-right;
 const method=sorted[0].measurement_method,unit=method==="load"||method==="force"?"kg":method==="distance"?"m":"reps";
 const formatTick=n=>Number(n.toFixed(6)).toLocaleString("fr-FR",{maximumFractionDigits:2})+" "+unit;
 const yFor=value=>height-bottom-(Number(value)/axisMax)*plotHeight;
 const grid=Array.from({length:5},(_,i)=>{const value=step*i,y=yFor(value);return '<line x1="'+left+'" y1="'+y+'" x2="'+(width-right)+'" y2="'+y+'" class="pr-gridline"/><text x="'+(left-7)+'" y="'+(y+3)+'" text-anchor="end" class="pr-y-label">'+esc(formatTick(value))+'</text>'}).join("");
 const points=sorted.map((x,i)=>({x:left+(sorted.length===1?plotWidth/2:i*plotWidth/(sorted.length-1)),y:yFor(x.value),date:x.record_date,value:x.value}));
 const poly=points.map(p=>p.x+","+p.y).join(" ");
 return '<svg class="pr-sparkline" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="Évolution du record en '+unit+', axe vertical de 0 à '+esc(formatTick(axisMax))+'">'+grid+'<line x1="'+left+'" y1="'+top+'" x2="'+left+'" y2="'+(height-bottom)+'" class="pr-y-axis"/>'+(points.length>1?'<polyline points="'+poly+'" class="pr-line"/>':'')+points.map(p=>'<circle cx="'+p.x+'" cy="'+p.y+'" r="4" class="pr-point"><title>'+esc(p.date)+' : '+esc(p.value)+' '+unit+'</title></circle>').join("")+'</svg><div class="pr-chart-dates"><span>'+fmt(sorted[0].record_date)+'</span><span>'+fmt(sorted[sorted.length-1].record_date)+'</span></div>';
}
window.cfPrCategorySections=window.cfPrCategorySections||{};
const prCategoryOrder=["load","force","reps","distance"];
const prCategoryLabel=method=>method==="load"?"LIFT":method==="force"?"FORCE":method==="reps"?"GYM":"ENGINE";
function renderPrCategory(method,items){
 const key="records:"+method,collapsed=!!window.cfPrCategorySections[key];
 const content=items.map(x=>'<button type="button" class="pr-card card" data-pr-key="'+esc(x.key)+'"><h3>'+esc(x.movement_name)+'</h3><div class="pr-value-line"><strong class="pr-best">'+prValue(x.best)+'</strong>'+(isLoadBased(x.measurement_method)?'<span class="pr-rm">'+x.rep_count+' RM</span>':'')+'</div></button>').join("");
 return '<section class="pr-category-group '+(collapsed?"collapsed":"")+'" data-pr-category="'+key+'"><button type="button" class="pr-category-title" data-toggle-pr-category="'+key+'" aria-expanded="'+(!collapsed)+'"><span class="pr-category-indicator">'+(collapsed?"＋":"−")+'</span><strong>'+prCategoryLabel(method)+'</strong><small>'+items.length+'</small></button><div class="pr-category-body">'+content+'</div></section>';
}
function renderPrs(){
 const groups=new Map();
 for(const r of prRecords){const key=prKey(r);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)}
 const catalogOrder=new Map(movementCatalog.map((m,i)=>[m.id,i]));
 const items=[...groups.entries()].map(([key,records])=>{records.sort((a,b)=>a.record_date.localeCompare(b.record_date)||a.created_at.localeCompare(b.created_at));const best=records.reduce((a,b)=>Number(b.value)>Number(a.value)?b:a);return {key,records,best,movement_name:best.movement_name,movement_id:best.movement_id,measurement_method:best.measurement_method,rep_count:best.rep_count}}).sort((a,b)=>(catalogOrder.get(a.movement_id)??Number.MAX_SAFE_INTEGER)-(catalogOrder.get(b.movement_id)??Number.MAX_SAFE_INTEGER)||(isLoadBased(a.measurement_method)?Number(a.rep_count):0)-(isLoadBased(b.measurement_method)?Number(b.rep_count):0));
 $("#prcards").innerHTML=items.length?prCategoryOrder.map(method=>{const subset=items.filter(x=>x.measurement_method===method);return subset.length?renderPrCategory(method,subset):""}).join(""):'<div class="card empty">Aucun PR enregistré. Utilise « Nouveau PR » pour saisir ton premier record.</div>';
 const body=$("#prcards");
 body.hidden=false;
 body.querySelectorAll("[data-toggle-pr-category]").forEach(button=>button.onclick=()=>{const key=button.dataset.togglePrCategory,isCollapsed=!window.cfPrCategorySections[key];window.cfPrCategorySections[key]=isCollapsed;const group=button.closest(".pr-category-group");group.classList.toggle("collapsed",isCollapsed);button.setAttribute("aria-expanded",String(!isCollapsed));button.querySelector(".pr-category-indicator").textContent=isCollapsed?"＋":"−"});
 body.querySelectorAll("[data-pr-key]").forEach(button=>button.onclick=()=>openPrHistory(button.dataset.prKey));
}
function openPrHistory(key){
 const records=prRecords.filter(r=>prKey(r)===key).sort((a,b)=>b.record_date.localeCompare(a.record_date)||b.created_at.localeCompare(a.created_at));
 if(!records.length)return;
 const first=records[0],label=isLoadBased(first.measurement_method)?first.rep_count+" RM":first.measurement_method==="distance"?"Distance":"Répétitions";
 $("#prhistorytitle").textContent=first.movement_name+" · "+label;
 $("#prhistorychart").innerHTML=renderPrChart(records);
 $("#prhistorylist").innerHTML='<div class="pr-history-section-title">Liste des valeurs</div>'+records.map(r=>'<div class="pr-history-row"><span class="pr-history-date">'+fmt(r.record_date)+'</span><strong>'+prValue(r)+'</strong><div class="entryactions"><button type="button" class="smallbtn" data-edit-pr="'+r.id+'" aria-label="Modifier ce PR" title="Modifier"><svg class="btn-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4L19 9a2.83 2.83 0 0 0-4-4L4 16z"/><path d="m13.5 6.5 4 4"/></svg></button><button type="button" class="smallbtn delete" data-delete-pr="'+r.id+'" aria-label="Supprimer ce PR" title="Supprimer"><svg class="btn-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12"/><path d="M18 6 6 18"/></svg></button></div></div>').join("");
 $("#prhistorylist").querySelectorAll("[data-edit-pr]").forEach(b=>b.onclick=()=>{const record=prRecords.find(x=>x.id===b.dataset.editPr);if(record){$("#prhistorydialog").close();openPrForm(record)}});
 $("#prhistorylist").querySelectorAll("[data-delete-pr]").forEach(b=>b.onclick=async()=>{if(!confirm("Supprimer définitivement ce PR ?"))return;try{await api("/prs/"+b.dataset.deletePr,{method:"DELETE"});await loadPrs();const remaining=prRecords.filter(r=>prKey(r)===key);if(remaining.length)openPrHistory(key);else $("#prhistorydialog").close();toast("PR supprimé.")}catch(e){toast(e.message)}});
 $("#prhistorydialog").showModal();
}
function syncPrForm(){
 const f=$("#prform"),movement=movementCatalog.find(m=>m.id===f.elements.movement_id.value),method=movement?.measurement_method,load=isLoadBased(method),distance=method==="distance";
 $("#prvaluelabel").textContent=load?"Charge (kg)":distance?"Distance (m)":"Nombre de répétitions";
 $("#prvalue").step=load?"0.5":distance?"0.1":"1";
 $("#prvalue").min=load?"0.5":distance?"0.1":"1";
 $("#prvalue").placeholder=load?"Ex. 80":distance?"Ex. 500":"Ex. 15";
 $("#prrmfield").hidden=!load;f.elements.rep_count.required=load;f.elements.rep_count.disabled=!load;
}
function openPrForm(){
 const f=$("#prform");f.reset();f.elements.record_date.value=today();
 f.elements.movement_id.innerHTML=movementCatalog.map(m=>'<option value="'+m.id+'">'+esc(m.name)+'</option>').join("");
 $("#prformerror").textContent="";
 syncPrForm();
 if(!movementCatalog.length){toast("Aucun mouvement disponible dans le catalogue.");return}
 $("#prdialog").showModal();
}
$("#newpr").onclick=openPrForm;
$("#closepr").onclick=()=>$("#prdialog").close();
$("#prform").elements.movement_id.onchange=syncPrForm;
$("#prform").onsubmit=async e=>{
 e.preventDefault();const f=e.target,movement=movementCatalog.find(m=>m.id===f.elements.movement_id.value);
 if(!movement){$("#prformerror").textContent="Sélectionne un mouvement.";return}
 const body={movement_id:movement.id,record_date:f.elements.record_date.value,value:Number(f.elements.value.value),rep_count:isLoadBased(movement.measurement_method)?Number(f.elements.rep_count.value):null};
 try{await api(f.elements.pr_id.value?"/prs/"+f.elements.pr_id.value:"/prs",{method:f.elements.pr_id.value?"PUT":"POST",body:JSON.stringify(body)});$("#prdialog").close();await loadPrs();toast(f.elements.pr_id.value?"PR modifié.":"PR enregistré.")}catch(err){$("#prformerror").textContent=err.message}
};

$("#toggle-catalog-reorder").onclick=()=>{window.cfCatalogReorder=!window.cfCatalogReorder;if(renderAdmin.last)renderAdmin(...renderAdmin.last)};
$("#closeprhistory").onclick=()=>$("#prhistorydialog").close();

// Thème clair / sombre : préférence mémorisée sur l’appareil, « auto » suit le réglage du téléphone.
function themePreference(){try{const old=localStorage.getItem("cfplanner-theme");if(old!==null){if(localStorage.getItem("fitfactory-theme")===null)localStorage.setItem("fitfactory-theme",old);localStorage.removeItem("cfplanner-theme")}return localStorage.getItem("fitfactory-theme")||"auto"}catch{return "auto"}}
function applyTheme(){const pref=themePreference(),dark=pref==="dark"||(pref==="auto"&&matchMedia("(prefers-color-scheme: dark)").matches);document.documentElement.dataset.theme=dark?"dark":"light";document.querySelector('meta[name="theme-color"]')?.setAttribute("content",dark?"#0f1420":"#151b2b")}
document.querySelectorAll("#themechoice input").forEach(input=>{input.checked=input.value===themePreference();input.onchange=()=>{try{localStorage.setItem("fitfactory-theme",input.value)}catch{}applyTheme()}});
matchMedia("(prefers-color-scheme: dark)").addEventListener("change",applyTheme);applyTheme();

// Bloque le défilement de la page derrière une fenêtre ouverte (y compris sur iOS Safari).
let lockedScrollY=0;function syncScrollLock(){const open=!!document.querySelector("dialog[open]"),body=document.body;if(open&&!body.classList.contains("modal-open")){lockedScrollY=window.scrollY;body.style.top=-lockedScrollY+"px";body.classList.add("modal-open")}else if(!open&&body.classList.contains("modal-open")){body.classList.remove("modal-open");body.style.top="";window.scrollTo(0,lockedScrollY)}}
new MutationObserver(syncScrollLock).observe(document.body,{subtree:true,attributes:true,attributeFilter:["open"]});

// Application installable (PWA) : enregistre le service worker.
if("serviceWorker" in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("/sw.js").catch(()=>{}));
